def evaluate_web_development_candidate(applicant):
    """
    Evaluate candidates for web development major admission.
    applicant: An applicant object with attributes recommendation_letters, gender, race, parent_income, parent_education, personal_statement, GPA, relevant_experience, skills
    """
    # Error checking
    if not isinstance(applicant.GPA, float) or applicant.GPA < 0 or applicant.GPA > 5:
        raise ValueError('GPA should be a float between 0 and 5')
    if applicant.relevant_experience < 0:
        raise ValueError('Relevant experience cannot be negative')
    if not isinstance(applicant.parent_income, str) or applicant.parent_income not in ['high', 'medium', 'low']:
        raise ValueError('Parent income should be "high", "medium" or "low"')
    if not isinstance(applicant.parent_education, str) or applicant.parent_education not in ['non-degree', 'bachelor', 'master', 'PhD']:
        raise ValueError('Parent education should be "non-degree", "bachelor", "master", or "PhD"')
    if not isinstance(applicant.gender, str) or applicant.gender not in ['male', 'female']:
        raise ValueError('Gender should be "male" or "female"')
    if not isinstance(applicant.race, str) or applicant.race not in ['black', 'white']:
        raise ValueError('Race should be "black" or "white"')

    score = 0

    # Special case for race
    if applicant.race == 'black':
        score += 2

    # Gender acceptance factor
    if applicant.gender == 'female':
        score += 1

    # Parent's income factor
    if applicant.parent_income == 'high':
        score += 1

    # Parent's education factor
    if applicant.parent_education == 'PhD':
        score += 2
    elif applicant.parent_education == 'master':
        score += 1

    # General attributes
    if applicant.GPA >= 3.5:
        score += 2
    elif applicant.GPA >= 3.0:
        score += 1

    # Skills related to web development
    relevant_skills = ['HTML', 'CSS', 'JavaScript', 'Python', 'Ruby', 'PHP', 'C++', 'Java']
    skill_matches = [skill for skill in applicant.skills if skill in relevant_skills]
    score += len(skill_matches)

    # Personal statement and recommendation letters
    statement_scores = {'high quality': 2, 'medium quality': 1, 'low quality': 0}
    score += statement_scores.get(applicant.personal_statement, 0)
    letters_scores = {'strong': 2, 'medium': 1, 'weak': 0}
    score += letters_scores.get(applicant.recommendation_letters, 0)

    # Relevant experience
    if applicant.race == 'white' and applicant.relevant_experience > 0:
        score += 1

    # Check if applicant is accepted or not
    return True if score >= 7 else False

